def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def spans(n, cuts):
        out, start = [], 0
        for p in cuts:
            if p > start:
                out.append((start, p))
            start = p + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    out = [row[:] for row in grid]
    source = None
    for r0, r1 in rs:
        for c0, c1 in cs:
            if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                source = (r0, r1, c0, c1)
                break
        if source:
            break
    if source:
        r0, r1, c0, c1 = source
        for a, b in rs:
            for x, y in cs:
                if (a, b, x, y) == source:
                    continue
                for i in range(min(b-a, r1-r0)):
                    for j in range(min(y-x, c1-c0)):
                        out[a+i][x+j] = grid[r0+i][c0+j]
    return out
